{"filepath": "src/satisfactory_planner/core/flow_builder.py", "content": """"Build FlowGraph from Document, with fatal error detection.

This module converts visual models (buildings, belts) into the flow graph
used for simulation. Fatal errors are detected during construction.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum, auto
from typing import TYPE_CHECKING

from satisfactory_planner.core.flow_models import (
    FlowEdge,
    FlowGraph,
    FlowNode,
    FlowPort,
    NodeType,
)
from satisfactory_planner.core.models import (
    BELT_CAPACITIES,
    Building,
    BuildingType,
    Scene,
)

if TYPE_CHECKING:
    from satisfactory_planner.core.models import Belt, Document, Recipe


class FatalErrorType(Enum):
    """Types of fatal errors that prevent model construction."""

    DISCONNECTED_BELT = auto()  # Belt missing source or dest
    ITEM_MISMATCH = auto()  # Belt connects incompatible item types
    MERGER_TYPE_CONFLICT = auto()  # Merger inputs have different item types
    RECIPE_NOT_SET = auto()  # Connected production building has no recipe
    SOURCELESS_CYCLE = auto()  # Loop with no external input


@dataclass
class FatalError:
    """A fatal error that prevents building the flow model."""

    error_type: FatalErrorType
    message: str
    element_id: str  # ID of the problematic element


@dataclass
class BuildResult:
    """Result of building a flow graph - either success or errors."""

    graph: FlowGraph | None = None
    errors: list[FatalError] = field(default_factory=list)

    @property
    def success(self) -> bool:
        return self.graph is not None and len(self.errors) == 0


def _get_node_type(building_type: BuildingType) -> NodeType:
    """Map building type to flow node type."""
    if building_type in (BuildingType.MINER_MK1, BuildingType.MINER_MK2, BuildingType.MINER_MK3):
        return NodeType.MINER
    if building_type == BuildingType.SPLITTER:
        return NodeType.SPLITTER
    if building_type == BuildingType.MERGER:
        return NodeType.MERGER
    if building_type == BuildingType.PORT_IN:
        return NodeType.PORT_IN
    if building_type == BuildingType.PORT_OUT:
        return NodeType.PORT_OUT
    return NodeType.PRODUCER


def _get_port_item_id(
    building: Building, is_input: bool, port_index: int, recipes: dict[str, Recipe]
) -> str | None:
    """Get the item ID for a port based on recipe."""
    if building.recipe_id is None:
        return None

    recipe = recipes.get(building.recipe_id)
    if recipe is None:
        return None

    if is_input:
        if port_index < len(recipe.inputs):
            return recipe.inputs[port_index].item_id
    else:
        if port_index < len(recipe.outputs):
            return recipe.outputs[port_index].item_id

    return None


def _build_flow_ports(
    building: Building, recipes: dict[str, Recipe]
) -> tuple[list[FlowPort], list[FlowPort]]:
    """Build input and output FlowPorts for a building."""
    inputs: list[FlowPort] = []
    outputs: list[FlowPort] = []

    if building.recipe_id and building.recipe_id in recipes:
        recipe = recipes[building.recipe_id].scaled(building.clock_speed)
        for item_rate in recipe.inputs:
            inputs.append(FlowPort(item_id=item_rate.item_id, rate=item_rate.rate))
        for item_rate in recipe.outputs:
            outputs.append(FlowPort(item_id=item_rate.item_id, rate=item_rate.rate))
    elif building.building_type == BuildingType.SPLITTER:
        # Splitter: 1 input, 3 outputs (item type determined by connection)
        inputs.append(FlowPort(item_id=None, rate=0))
        for _ in range(3):
            outputs.append(FlowPort(item_id=None, rate=0))
    elif building.building_type == BuildingType.MERGER:
        # Merger: 3 inputs, 1 output (item type determined by connection)
        for _ in range(3):
            inputs.append(FlowPort(item_id=None, rate=0))
        outputs.append(FlowPort(item_id=None, rate=0))

    return inputs, outputs


def _is_production_building(building_type: BuildingType) -> bool:
    """Check if building type requires a recipe."""
    return building_type not in (
        BuildingType.SPLITTER,
        BuildingType.MERGER,
        BuildingType.MINER_MK1,
        BuildingType.MINER_MK2,
        BuildingType.MINER_MK3,
        BuildingType.PORT_IN,
        BuildingType.PORT_OUT,
    )


def _has_connections(building_id: str, belts: dict[str, Belt]) -> bool:
    """Check if a building has any belt connections."""
    for belt in belts.values():
        if belt.source_building_id == building_id or belt.dest_building_id == building_id:
            return True
    return False


def _find_logistics_loop(graph: FlowGraph) -> list[str] | None:
    """Find a pure logistics loop (splitters/mergers only, no producers).

    Returns the cycle as a list of node IDs, or None if no such loop exists.
    """
    logistics_types = {NodeType.SPLITTER, NodeType.MERGER}

    def dfs(node_id: str, path: list[str], visited: set[str]) -> list[str] | None:
        if node_id in path:
            cycle_start = path.index(node_id)
            return path[cycle_start:] + [node_id]

        node = graph.nodes.get(node_id)
        if node is None or node.node_type not in logistics_types:
            return None

        if node_id in visited:
            return None
        visited.add(node_id)

        path.append(node_id)
        for edge in graph.get_outgoing_edges(node_id):
            result = dfs(edge.dest_node_id, path, visited)
            if result:
                return result
        path.pop()
        return None

    visited: set[str] = set()
    for node_id, node in graph.nodes.items():
        if node.node_type in logistics_types and node_id not in visited:
            result = dfs(node_id, [], visited)
            if result:
                return result

    return None


def build_flow_graph(document: Document, recipes: dict[str, Recipe]) -> BuildResult:
    """Build a FlowGraph from a Document.

    Args:
        document: The document to build from
        recipes: Dict of recipe_id -> Recipe for looking up recipes

    Returns:
        BuildResult with either a valid graph or a list of fatal errors.
    """
    errors: list[FatalError] = []
    graph = FlowGraph()

    # Build from all scenes (document + rooms)
    _build_scene(document, recipes, graph, errors)

    # Also build from room contents (for room placements)
    for placement in document.room_placements.values():
        room = document.rooms.get(placement.room_id)
        if room:
            _build_scene(room, recipes, graph, errors)

    if errors:
        return BuildResult(errors=errors)

    # Phase: Check for pure logistics loops
    logistics_loop = _find_logistics_loop(graph)
    if logistics_loop:
        errors.append(
            FatalError(
                error_type=FatalErrorType.SOURCELESS_CYCLE,
                message=f"Pure logistics loop detected: {' -> '.join(logistics_loop)}",
                element_id=logistics_loop[0],
            )
        )

    # Phase: Check merger type conflicts
    for node in graph.nodes.values():
        if node.node_type == NodeType.MERGER:
            incoming_edges = graph.get_incoming_edges(node.id)
            item_ids = {e.item_id for e in incoming_edges if e.item_id is not None}
            if len(item_ids) > 1:
                errors.append(
                    FatalError(
                        error_type=FatalErrorType.MERGER_TYPE_CONFLICT,
                        message=f"Merger {node.id} has mixed item types: {item_ids}",
                        element_id=node.id,
                    )
                )

    if errors:
        return BuildResult(errors=errors)

    return BuildResult(graph=graph)


def _build_scene(
    scene: Scene,
    recipes: dict[str, Recipe],
    graph: FlowGraph,
    errors: list[FatalError],
) -> None:
    """Build flow graph nodes and edges from a scene (Document or Room)."""
    # Phase 1: Check for disconnected belts
    for belt_id, belt in scene.belts.items():
        if belt.source_building_id is None:
            errors.append(
                FatalError(
                    error_type=FatalErrorType.DISCONNECTED_BELT,
                    message=f"Belt {belt_id} has no source building",
                    element_id=belt_id,
                )
            )
        elif belt.source_building_id not in scene.buildings:
            errors.append(
                FatalError(
                    error_type=FatalErrorType.DISCONNECTED_BELT,
                    message=f"Belt {belt_id} source building not found",
                    element_id=belt_id,
                )
            )

        if belt.dest_building_id is None:
            errors.append(
                FatalError(
                    error_type=FatalErrorType.DISCONNECTED_BELT,
                    message=f"Belt {belt_id} has no destination building",
                    element_id=belt_id,
                )
            )
        elif belt.dest_building_id not in scene.buildings:
            errors.append(
                FatalError(
                    error_type=FatalErrorType.DISCONNECTED_BELT,
                    message=f"Belt {belt_id} destination building not found",
                    element_id=belt_id,
                )
            )

    # Phase 2: Check for missing recipes on connected production buildings
    for building_id, building in scene.buildings.items():
        if (
            _is_production_building(building.building_type)
            and _has_connections(building_id, scene.belts)
            and building.recipe_id is None
        ):
            errors.append(
                FatalError(
                    error_type=FatalErrorType.RECIPE_NOT_SET,
                    message=f"Building {building_id} ({building.building_type.value}) has no recipe",
                    element_id=building_id,
                )
            )

    if errors:
        return

    # Phase 3: Build nodes
    for building_id, building in scene.buildings.items():
        inputs, outputs = _build_flow_ports(building, recipes)
        node = FlowNode(
            id=building_id,
            node_type=_get_node_type(building.building_type),
            building_id=building_id,
            recipe_id=building.recipe_id,
            clock_speed=building.clock_speed,
            inputs=inputs,
            outputs=outputs,
        )
        graph.add_node(node)

    # Phase 4: Build edges and check item type compatibility
    for belt_id, belt in scene.belts.items():
        assert belt.source_building_id is not None
        assert belt.dest_building_id is not None

        source_building = scene.buildings[belt.source_building_id]
        dest_building = scene.buildings[belt.dest_building_id]

        source_item_id = _get_port_item_id(source_building, False, belt.source_port_index, recipes)
        dest_item_id = _get_port_item_id(dest_building, True, belt.dest_port_index, recipes)

        # Check item type mismatch (only if both are known)
        if (
            source_item_id is not None
            and dest_item_id is not None
            and source_item_id != dest_item_id
        ):
            errors.append(
                FatalError(
                    error_type=FatalErrorType.ITEM_MISMATCH,
                    message=f"Belt {belt_id} connects {source_item_id} to {dest_item_id}",
                    element_id=belt_id,
                )
            )
            continue

        # Determine the item type for this edge
        item_id = source_item_id or dest_item_id

        edge = FlowEdge(
            id=belt_id,
            belt_id=belt_id,
            source_node_id=belt.source_building_id,
            source_port_index=belt.source_port_index,
            dest_node_id=belt.dest_building_id,
            dest_port_index=belt.dest_port_index,
            capacity=BELT_CAPACITIES[belt.tier],
            item_id=item_id,
        )
        graph.add_edge(edge)
"}

{"filepath": "src/satisfactory_planner/core/flow_lp_solver.py", "content": """"LP-based flow solver.

Solves for steady-state flow rates using linear programming.
Uses pylinprog (pure Python simplex) instead of scipy for smaller package size.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from satisfactory_planner.core.flow_models import (
    BuildingEfficiency,
    FlowGraph,
    FlowNode,
    LimitingFactor,
    NodeType,
)
from satisfactory_planner.core.linprog import RESOLUTION_SOLVED, linsolve


@dataclass
class SolvedModel:
    """Result of solving flow rates."""

    graph: FlowGraph
    flows: dict[str, float] = field(default_factory=dict)  # edge_id → flow rate
    efficiencies: dict[str, BuildingEfficiency] = field(
        default_factory=dict
    )  # node_id → efficiency
    success: bool = True
    message: str = ""


def _get_downstream_demand(node: FlowNode, port_index: int) -> float | None:
    """Get the demand of a node's input port.

    For producers, this is the recipe input rate.
    For splitters/mergers, we return None (no fixed demand).
    """
    if node.node_type == NodeType.PRODUCER:
        if port_index < len(node.inputs):
            return node.inputs[port_index].rate
    elif node.node_type == NodeType.SINK:
        # Sinks consume everything, no limit
        return None
    # Splitters/mergers don't have fixed demand
    return None


def solve_flows(graph: FlowGraph) -> SolvedModel:
    """Solve for steady-state flow rates using LP.

    We solve WITHOUT belt capacity constraints to get "ideal" flows.
    Capacity checking happens in the warning detection phase.

    The LP formulation:
    - Variables: one flow rate per edge
    - Constraints: flow conservation at each node
    - Objective: maximize total flow (to fill the factory)
    """
    if not graph.edges:
        # No edges = no flows to solve
        return SolvedModel(graph=graph, flows={})

    # Create edge index mapping
    edge_ids = list(graph.edges.keys())
    edge_to_idx = {eid: i for i, eid in enumerate(edge_ids)}
    n_edges = len(edge_ids)

    # We'll build equality constraints: A_eq @ x = b_eq
    # And inequality constraints: A_ub @ x <= b_ub
    equality_rows: list[list[float]] = []
    equality_rhs: list[float] = []
    inequality_rows: list[list[float]] = []
    inequality_rhs: list[float] = []

    for node_id, node in graph.nodes.items():
        incoming = graph.get_incoming_edges(node_id)
        outgoing = graph.get_outgoing_edges(node_id)

        if node.node_type == NodeType.MINER:
            # Miner: no inputs, output = production rate
            for i, out_edge in enumerate(outgoing):
                if i < len(node.outputs):
                    row = [0.0] * n_edges
                    row[edge_to_idx[out_edge.id]] = 1.0
                    equality_rows.append(row)
                    equality_rhs.append(node.outputs[i].rate)

        elif node.node_type == NodeType.PRODUCER:
            # Producer: outputs are LIMITED by downstream demand (inequality)
            for i, out_edge in enumerate(outgoing):
                if i < len(node.outputs):
                    dest_node = graph.nodes[out_edge.dest_node_id]
                    demand = _get_downstream_demand(dest_node, out_edge.dest_port_index)
                    if demand is not None:
                        row = [0.0] * n_edges
                        row[edge_to_idx[out_edge.id]] = 1.0
                        inequality_rows.append(row)
                        inequality_rhs.append(demand)

                    # Output also can't exceed production capacity
                    row = [0.0] * n_edges
                    row[edge_to_idx[out_edge.id]] = 1.0
                    inequality_rows.append(row)
                    inequality_rhs.append(node.outputs[i].rate)

            if not incoming:
                # No input constraints - treat as source
                pass
            else:
                # Inputs are limited by what upstream can provide
                for i, in_edge in enumerate(incoming):
                    if i < len(node.inputs):
                        row = [0.0] * n_edges
                        row[edge_to_idx[in_edge.id]] = 1.0
                        inequality_rows.append(row)
                        inequality_rhs.append(node.inputs[i].rate)

                # Recipe ratio constraint
                if outgoing and node.inputs and node.outputs:
                    ref_in_rate = node.inputs[0].rate
                    ref_out_rate = node.outputs[0].rate
                    if ref_in_rate > 0 and ref_out_rate > 0:
                        ref_in_edge = incoming[0]
                        ref_out_edge = outgoing[0]
                        row = [0.0] * n_edges
                        row[edge_to_idx[ref_in_edge.id]] = ref_out_rate
                        row[edge_to_idx[ref_out_edge.id]] = -ref_in_rate
                        equality_rows.append(row)
                        equality_rhs.append(0.0)

        elif node.node_type == NodeType.SPLITTER:
            if incoming and outgoing:
                # Conservation: sum(outputs) <= sum(inputs)
                row = [0.0] * n_edges
                for out_edge in outgoing:
                    row[edge_to_idx[out_edge.id]] = 1.0
                for in_edge in incoming:
                    row[edge_to_idx[in_edge.id]] = -1.0
                inequality_rows.append(row)
                inequality_rhs.append(0.0)

                # Each output is limited by downstream demand
                for out_edge in outgoing:
                    dest_node = graph.nodes[out_edge.dest_node_id]
                    demand = _get_downstream_demand(dest_node, out_edge.dest_port_index)
                    if demand is not None:
                        row = [0.0] * n_edges
                        row[edge_to_idx[out_edge.id]] = 1.0
                        inequality_rows.append(row)
                        inequality_rhs.append(demand)

        elif node.node_type == NodeType.MERGER:
            if incoming and outgoing:
                row = [0.0] * n_edges
                for in_edge in incoming:
                    row[edge_to_idx[in_edge.id]] = 1.0
                for out_edge in outgoing:
                    row[edge_to_idx[out_edge.id]] = -1.0
                equality_rows.append(row)
                equality_rhs.append(0.0)

        elif node.node_type in (NodeType.SINK, NodeType.PORT_OUT):
            # Sinks just consume whatever comes in
            pass

        elif node.node_type == NodeType.PORT_IN:
            # External input: output = specified rate
            for i, out_edge in enumerate(outgoing):
                if i < len(node.outputs):
                    row = [0.0] * n_edges
                    row[edge_to_idx[out_edge.id]] = 1.0
                    equality_rows.append(row)
                    equality_rhs.append(node.outputs[i].rate)

    # Objective: maximize total flow (minimize negative flow)
    c = [-1.0] * n_edges

    # All variables are non-negative (flow rates >= 0)
    nonneg_vars = list(range(n_edges))

    # Solve using pylinprog
    resolution, solution = linsolve(
        c,
        ineq_left=inequality_rows,
        ineq_right=inequality_rhs,
        eq_left=equality_rows,
        eq_right=equality_rhs,
        nonneg_variables=nonneg_vars,
    )

    if resolution != RESOLUTION_SOLVED:
        return SolvedModel(
            graph=graph,
            flows={},
            success=False,
            message=f"LP solver failed: {resolution}",
        )

    # Extract flows
    flows = {edge_ids[i]: max(0.0, solution[i]) for i in range(n_edges)}

    # Compute duty cycles for all producer nodes
    efficiencies = _compute_efficiencies(graph, flows)

    return SolvedModel(graph=graph, flows=flows, efficiencies=efficiencies, success=True)


def _compute_efficiencies(
    graph: FlowGraph, flows: dict[str, float]
) -> dict[str, BuildingEfficiency]:
    """Compute duty cycle and limiting factor for each producer."""
    efficiencies: dict[str, BuildingEfficiency] = {}

    for node_id, node in graph.nodes.items():
        if node.node_type != NodeType.PRODUCER:
            continue

        outgoing = graph.get_outgoing_edges(node_id)
        incoming = graph.get_incoming_edges(node_id)

        if outgoing and node.outputs:
            intended_rate = node.outputs[0].rate
            actual_rate = flows.get(outgoing[0].id, 0.0)
        elif incoming and node.inputs:
            intended_rate = node.inputs[0].rate
            actual_rate = flows.get(incoming[0].id, 0.0)
        else:
            continue

        duty_cycle = actual_rate / intended_rate if intended_rate > 0 else 1.0
        limiting_factor, limiting_details = _find_limiting_factor(graph, flows, node, duty_cycle)

        efficiencies[node_id] = BuildingEfficiency(
            building_id=node.building_id or node_id,
            node_id=node_id,
            intended_rate=intended_rate,
            actual_rate=actual_rate,
            duty_cycle=min(1.0, duty_cycle),
            limiting_factor=limiting_factor,
            limiting_details=limiting_details,
        )

    return efficiencies


def _find_limiting_factor(
    graph: FlowGraph,
    flows: dict[str, float],
    node: FlowNode,
    duty_cycle: float,
) -> tuple[LimitingFactor, str]:
    """Determine why a producer isn't at 100% duty cycle."""
    if duty_cycle >= 0.999:
        return LimitingFactor.NONE, "Running at full capacity"

    incoming = graph.get_incoming_edges(node.id)
    outgoing = graph.get_outgoing_edges(node.id)

    # Check if input-starved
    for i, in_edge in enumerate(incoming):
        if i < len(node.inputs):
            actual_input = flows.get(in_edge.id, 0.0)
            if actual_input < node.inputs[i].rate - 0.01:
                edge = graph.edges[in_edge.id]
                if actual_input >= edge.capacity - 0.01:
                    return (
                        LimitingFactor.BELT_CAPACITY,
                        f"Input belt {in_edge.id} at capacity ({edge.capacity}/min)",
                    )
                return (
                    LimitingFactor.INPUT_STARVED,
                    f"Input {node.inputs[i].item_id}: getting {actual_input:.1f}, need {node.inputs[i].rate:.1f}/min",
                )

    # Check if downstream-limited
    for i, out_edge in enumerate(outgoing):
        if i < len(node.outputs):
            actual_output = flows.get(out_edge.id, 0.0)
            if actual_output < node.outputs[i].rate - 0.01:
                edge = graph.edges[out_edge.id]
                if actual_output >= edge.capacity - 0.01:
                    return (
                        LimitingFactor.BELT_CAPACITY,
                        f"Output belt {out_edge.id} at capacity ({edge.capacity}/min)",
                    )
                return (
                    LimitingFactor.DOWNSTREAM,
                    f"Downstream only consumes {actual_output:.1f}/min",
                )

    return LimitingFactor.NONE, "Unknown"
"}

{"filepath": "src/satisfactory_planner/core/detectors/dangling.py", "content": """"Dangling port detection.

Detects unconnected ports and reports them as info-level warnings.
"""

from satisfactory_planner.core.flow_models import FlowGraph, NodeType
from satisfactory_planner.core.flow_solver import Warning, WarningType


def detect_dangling_ports(graph: FlowGraph) -> list[Warning]:
    """Detect unconnected input/output ports on production buildings.

    Returns info-level warnings explaining what assumptions were made:
    - Unconnected inputs: "Treated as infinite source"
    - Unconnected outputs: "Treated as sink (items discarded)"
    """
    warnings: list[Warning] = []

    for node_id, node in graph.nodes.items():
        if node.node_type != NodeType.PRODUCER:
            continue

        # Check for unconnected inputs
        incoming = graph.get_incoming_edges(node_id)
        connected_input_indices = {e.dest_port_index for e in incoming}

        unconnected_inputs: list[str] = []
        for i, input_port in enumerate(node.inputs):
            if i not in connected_input_indices and input_port.item_id:
                unconnected_inputs.append(input_port.item_id)

        if unconnected_inputs and not incoming:
            items = ", ".join(unconnected_inputs)
            warnings.append(
                Warning(
                    type=WarningType.LEFTOVER_ITEMS,
                    message=f"{node_id}: No inputs connected. Assuming infinite supply of {items}.",
                    element_id=node_id,
                    severity=0.1,
                )
            )
        elif unconnected_inputs:
            items = ", ".join(unconnected_inputs)
            warnings.append(
                Warning(
                    type=WarningType.RESOURCE_UNDERFLOW,
                    message=f"{node_id}: Missing input(s): {items}. Building will not function correctly.",
                    element_id=node_id,
                    severity=0.8,
                )
            )

        # Check for unconnected outputs
        outgoing = graph.get_outgoing_edges(node_id)
        connected_output_indices = {e.source_port_index for e in outgoing}

        unconnected_outputs: list[str] = []
        for i, output_port in enumerate(node.outputs):
            if i not in connected_output_indices and output_port.item_id:
                unconnected_outputs.append(output_port.item_id)

        if unconnected_outputs and not outgoing:
            items = ", ".join(unconnected_outputs)
            warnings.append(
                Warning(
                    type=WarningType.LEFTOVER_ITEMS,
                    message=f"{node_id}: No outputs connected. Production of {items} will be sunk.",
                    element_id=node_id,
                    severity=0.1,
                )
            )
        elif unconnected_outputs:
            items = ", ".join(unconnected_outputs)
            warnings.append(
                Warning(
                    type=WarningType.LEFTOVER_ITEMS,
                    message=f"{node_id}: Unconnected output(s): {items}. Items will be sunk.",
                    element_id=node_id,
                    severity=0.3,
                )
            )

    return warnings
"}

{"filepath": "src/satisfactory_planner/core/detectors/overcapacity.py", "content": """"Belt overcapacity detection.

Detects belts where ideal flow exceeds belt capacity.
Filters to show only the FIRST bottleneck in each chain.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from satisfactory_planner.core.flow_solver import Warning, WarningType

if TYPE_CHECKING:
    from satisfactory_planner.core.flow_lp_solver import SolvedModel


def detect_overcapacity(model: SolvedModel) -> list[Warning]:
    """Detect belt overcapacity warnings.

    Returns warnings only for belts that are the FIRST bottleneck
    in their flow chain (upstream belts are not overcapacity).
    """
    if not model.success:
        return []

    # First pass: find all overcapacity belts
    overcap_edges: set[str] = set()
    for edge_id, flow in model.flows.items():
        edge = model.graph.edges[edge_id]
        if flow > edge.capacity:
            overcap_edges.add(edge_id)

    if not overcap_edges:
        return []

    # Second pass: filter out belts that have an upstream overcapacity belt
    filtered_overcap: set[str] = set()

    for edge_id in overcap_edges:
        if not _has_upstream_overcapacity(model, edge_id, overcap_edges):
            filtered_overcap.add(edge_id)

    # Generate warnings for filtered set
    warnings: list[Warning] = []
    for edge_id in filtered_overcap:
        edge = model.graph.edges[edge_id]
        flow = model.flows[edge_id]
        warnings.append(
            Warning(
                type=WarningType.BELT_OVERCAPACITY,
                message=f"Belt {edge_id}: flow {flow:.1f}/min exceeds capacity {edge.capacity}/min",
                element_id=edge_id,
                severity=(flow - edge.capacity) / edge.capacity,
            )
        )

    return warnings


def _has_upstream_overcapacity(
    model: SolvedModel, edge_id: str, overcap_edges: set[str], visited: set[str] | None = None
) -> bool:
    """Check if there's an overcapacity belt upstream of this edge."""
    if visited is None:
        visited = set()

    if edge_id in visited:
        return False
    visited.add(edge_id)

    edge = model.graph.edges[edge_id]
    source_node = model.graph.nodes[edge.source_node_id]

    incoming = model.graph.get_incoming_edges(source_node.id)

    for in_edge in incoming:
        if in_edge.item_id == edge.item_id or in_edge.item_id is None or edge.item_id is None:
            if in_edge.id in overcap_edges:
                return True
            if _has_upstream_overcapacity(model, in_edge.id, overcap_edges, visited):
                return True

    return False
"}

{"filepath": "src/satisfactory_planner/core/detectors/underflow.py", "content": """"Underflow detection with causal chain backtracking.

Detects when demand exceeds supply and builds a causal chain
showing WHY the underflow occurred.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from satisfactory_planner.core.flow_models import NodeType
from satisfactory_planner.core.flow_solver import Warning, WarningType

if TYPE_CHECKING:
    from satisfactory_planner.core.flow_lp_solver import SolvedModel


def detect_underflow(model: SolvedModel) -> list[Warning]:
    """Detect underflow warnings with causal chains.

    An underflow occurs when a node's input receives less than demanded.
    We backchain to find the root cause.
    """
    if not model.success:
        return []

    warnings: list[Warning] = []

    for node_id, node in model.graph.nodes.items():
        if node.node_type != NodeType.PRODUCER:
            continue

        incoming = model.graph.get_incoming_edges(node_id)
        outgoing = model.graph.get_outgoing_edges(node_id)

        if not incoming and outgoing:
            # Has outputs but no inputs - treat as source
            continue
        if not incoming and not outgoing:
            # Orphaned building
            for i, input_port in enumerate(node.inputs):
                if input_port.rate > 0:
                    warnings.append(
                        Warning(
                            type=WarningType.RESOURCE_UNDERFLOW,
                            message=f"{node_id}: input {i} ({input_port.item_id}) not connected",
                            element_id=node_id,
                            severity=1.0,
                        )
                    )
            continue

        for i, input_port in enumerate(node.inputs):
            if input_port.rate <= 0:
                continue

            # Find the edge feeding this input
            feeding_edge = None
            for edge in incoming:
                if edge.dest_port_index == i:
                    feeding_edge = edge
                    break

            if feeding_edge is None:
                warnings.append(
                    Warning(
                        type=WarningType.RESOURCE_UNDERFLOW,
                        message=f"{node_id}: input {i} ({input_port.item_id}) not connected",
                        element_id=node_id,
                        severity=1.0,
                    )
                )
                continue

            actual_flow = model.flows.get(feeding_edge.id, 0.0)
            demanded = input_port.rate

            if actual_flow < demanded - 0.01:
                caused_by = _build_causal_chain(model, feeding_edge.id, demanded)
                warnings.append(
                    Warning(
                        type=WarningType.RESOURCE_UNDERFLOW,
                        message=f"{node_id}: {input_port.item_id} {actual_flow:.1f} < {demanded:.1f}/min demanded",
                        element_id=node_id,
                        severity=(demanded - actual_flow) / demanded,
                        caused_by=caused_by,
                    )
                )

    return warnings


def _build_causal_chain(
    model: SolvedModel, edge_id: str, demanded: float, visited: set[str] | None = None
) -> list[Warning]:
    """Build causal chain showing why flow is insufficient."""
    if visited is None:
        visited = set()

    if edge_id in visited:
        return []
    visited.add(edge_id)

    causes: list[Warning] = []
    edge = model.graph.edges[edge_id]
    actual_flow = model.flows.get(edge_id, 0.0)

    # Check if this belt is the bottleneck
    if actual_flow >= edge.capacity - 0.01:
        causes.append(
            Warning(
                type=WarningType.BELT_OVERCAPACITY,
                message=f"Belt {edge_id} at capacity ({edge.capacity}/min)",
                element_id=edge_id,
                severity=1.0,
            )
        )
        return causes

    # Otherwise, look upstream
    source_node = model.graph.nodes[edge.source_node_id]

    if source_node.node_type == NodeType.PRODUCER:
        for output in source_node.outputs:
            if output.item_id == edge.item_id and output.rate < demanded:
                causes.append(
                    Warning(
                        type=WarningType.PRODUCTION_UNDERFLOW,
                        message=f"{source_node.id} produces {output.rate:.1f}/min, need {demanded:.1f}/min",
                        element_id=source_node.id,
                        severity=(demanded - output.rate) / demanded,
                    )
                )

    elif source_node.node_type == NodeType.MINER:
        for output in source_node.outputs:
            if output.rate < demanded:
                causes.append(
                    Warning(
                        type=WarningType.RESOURCE_UNDERFLOW,
                        message=f"Miner {source_node.id} outputs {output.rate:.1f}/min, need {demanded:.1f}/min",
                        element_id=source_node.id,
                        severity=(demanded - output.rate) / demanded,
                    )
                )

    elif source_node.node_type in (NodeType.SPLITTER, NodeType.MERGER):
        incoming = model.graph.get_incoming_edges(source_node.id)
        for in_edge in incoming:
            causes.extend(_build_causal_chain(model, in_edge.id, demanded, visited))

    return causes
"}

